// HasConversation applies the HasEdge predicate on the "conversation" edge.
func HasConversation() predicate.EmailOutboundMessage {
	return predicate.EmailOutboundMessage(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ConversationTable, ConversationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasConversationWith applies the HasEdge predicate on the "conversation" edge with a given conditions (other predicates).
func HasConversationWith(preds ...predicate.EmailConversation) predicate.EmailOutboundMessage {
	return predicate.EmailOutboundMessage(func(s *sql.Selector) {
		step := newConversationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EmailOutboundMessage) predicate.EmailOutboundMessage {
	return predicate.EmailOutboundMessage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EmailOutboundMessage) predicate.EmailOutboundMessage {
	return predicate.EmailOutboundMessage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EmailOutboundMessage) predicate.EmailOutboundMessage {
	return predicate.EmailOutboundMessage(sql.NotPredicates(p))
}
